@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase small fw-bold">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link w-100 text-start @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionSelected.InvokeAsync(section)">
                    <span class="me-2">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    min-width: 220px;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    background: #f8f9fa;
    min-height: calc(100vh - 7rem);
}

.settings-sidebar .nav-link {
    color: #495057;
    padding: 0.6rem 1.25rem;
    border-radius: 0;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<div class="change-password-panel">
    <button class="btn btn-outline-secondary mb-3" @onclick="ToggleExpanded">
        @(IsExpanded ? "▼" : "▶") Change Password
    </button>

    @if (IsExpanded)
    {
        <div class="card card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="CurrentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="NewPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="ConfirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="alert alert-danger py-2">@ErrorMessage</div>
            }
            @if (ShowSuccess)
            {
                <div class="alert alert-success py-2">Password updated successfully.</div>
            }

            <div>
                <button class="btn btn-primary" @onclick="HandleSubmit" disabled="@IsSubmitting">
                    @(IsSubmitting ? "Updating…" : "Update Password")
                </button>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? ErrorMessage;
    private bool ShowSuccess;
    private bool IsSubmitting;

    private void ToggleExpanded() => IsExpanded = !IsExpanded;

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        ShowSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) ||
            string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All password fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }

        if (NewPassword.Length < 8)
        {
            ErrorMessage = "New password must be at least 8 characters.";
            return;
        }

        IsSubmitting = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            ShowSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            ErrorMessage = ex.Message;
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

@if (IsVisible)
{
    <div class="modal-backdrop show" @onclick="HandleCancel"></div>
    <div class="modal d-block" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="HandleCancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@DeviceName</strong>?</p>
                    <p class="text-muted small">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="HandleCancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="HandleConfirm">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool IsVisible { get; set; }
    [Parameter] public string DeviceName { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task HandleConfirm() => await OnConfirm.InvokeAsync();
    private async Task HandleCancel() => await OnCancel.InvokeAsync();
}

@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<div class="appearance-preview card @ThemeClass @FontSizeClass @(CompactMode ? "compact" : "")">
    <div class="card-header">
        <strong>Preview</strong>
    </div>
    <div class="card-body">
        <h6>Sample Heading</h6>
        <p>This is how your content will look with the selected settings.</p>
        <div class="d-flex gap-2 mb-2">
            <span class="badge bg-primary">Badge</span>
            <span class="badge bg-success">Active</span>
            <span class="badge bg-warning text-dark">Pending</span>
        </div>
        <button class="btn btn-primary btn-sm me-2">Primary Button</button>
        <button class="btn btn-outline-secondary btn-sm">Secondary</button>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public bool CompactMode { get; set; }

    private string ThemeClass => Theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string FontSizeClass => FontSize switch
    {
        "Small" => "preview-font-sm",
        "Large" => "preview-font-lg",
        _ => "preview-font-md"
    };
}

.appearance-preview {
    transition: all 0.2s ease;
    margin-top: 1rem;
}

.preview-light {
    background: #ffffff;
    color: #212529;
    border-color: #dee2e6;
}

.preview-light .card-header {
    background: #f8f9fa;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .card-header {
    background: #181825;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .btn-outline-secondary {
    color: #a6adc8;
    border-color: #585b70;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
    border-color: #adb5bd;
}

.preview-system .card-header {
    background: rgba(0, 0, 0, 0.05);
}

.preview-font-sm {
    font-size: 0.8rem;
}

.preview-font-md {
    font-size: 1rem;
}

.preview-font-lg {
    font-size: 1.15rem;
}

.compact .card-body {
    padding: 0.5rem 0.75rem;
}

.compact .card-body p {
    margin-bottom: 0.25rem;
}

.compact .card-body h6 {
    margin-bottom: 0.25rem;
}

@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase small fw-bold">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
