@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Profile</h4>

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="EditName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="EditEmail" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
            </div>
        </div>
        <div class="col-md-4">
            <div class="avatar-preview text-center">
                <label class="form-label">Avatar</label>
                <div class="mb-2">
                    @if (!string.IsNullOrWhiteSpace(EditAvatarUrl))
                    {
                        <img src="@EditAvatarUrl" alt="Avatar" class="rounded-circle" width="120" height="120" />
                    }
                    else
                    {
                        <div class="avatar-placeholder rounded-circle d-inline-flex align-items-center justify-content-center">
                            <span class="fs-1">👤</span>
                        </div>
                    }
                </div>
                <input type="text" class="form-control form-control-sm" placeholder="Avatar URL" @bind="EditAvatarUrl" />
            </div>
        </div>
    </div>

    @if (ShowSuccess)
    {
        <div class="alert alert-success py-2 mt-2">Profile saved successfully!</div>
