<div class="settings-section">
    <h4 class="mb-4">Security</h4>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <hr />

    <div class="mb-4">
        <h6>Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@TwoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">
                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                </label>
            </div>
            <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(TwoFactorEnabled ? "✓ Active" : "✗ Inactive")
            </span>
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted small mt-2 mb-0">
                Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }
    </div>

    <hr />

    <div class="mb-3">
        <h6>Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        var isCurrent = session == Settings.Sessions.FirstOrDefault();
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-info ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(StatusMessage))
    {
        <div class="alert @StatusCss py-2">@StatusMessage</div>
    }

    <RevokeSessionDialog IsVisible="ShowRevokeDialog"
                         DeviceName="@(SessionToRevoke?.Device ?? "")"
                         OnConfirm="HandleRevokeConfirmed"
                         OnCancel="HandleRevokeCancel" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled => Settings.TwoFactorEnabled;
    private bool ShowRevokeDialog;
    private ActiveSession? SessionToRevoke;
    private string? StatusMessage;
    private string StatusCss = "alert-success";

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await OnChangePassword.InvokeAsync(args);
    }

    private void PromptRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeDialog = true;
    }

    private async Task HandleRevokeConfirmed()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            StatusMessage = $"Session on {SessionToRevoke.Device} revoked.";
            StatusCss = "alert-success";
        }
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private void HandleRevokeCancel()
    {
        ShowRevokeDialog = false;
        SessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

