+    }
+
+    <div class="mt-3 d-flex gap-2">
+        <button class="btn btn-primary" @onclick="HandleSave" disabled="@IsSaving">
+            @(IsSaving ? "Saving…" : "Save Changes")
+        </button>
+        <button class="btn btn-outline-secondary" @onclick="HandleDiscard">Discard Changes</button>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
+    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }
+
+    private string EditName = "";
+    private string EditEmail = "";
+    private string EditBio = "";
+    private string EditAvatarUrl = "";
+    private bool IsSaving;
+    private bool ShowSuccess;
+
+    protected override void OnParametersSet()
+    {
+        if (!_initialized)
+        {
+            ResetFields();
+            _initialized = true;
+        }
+    }
+
+    private bool _initialized;
+
+    private void ResetFields()
+    {
+        EditName = Profile.DisplayName;
+        EditEmail = Profile.Email;
+        EditBio = Profile.Bio;
+        EditAvatarUrl = Profile.AvatarUrl;
+        ShowSuccess = false;
+    }
+
+    private async Task HandleSave()
+    {
+        IsSaving = true;
+        ShowSuccess = false;
+        try
+        {
+            var updated = new UserProfile(EditName, EditEmail, EditAvatarUrl, EditBio);
+            await OnSave.InvokeAsync(updated);
+            ShowSuccess = true;
+            _initialized = false; // Allow re-sync on next parameter set
+        }
+        finally
+        {
+            IsSaving = false;
+        }
+    }
+
+    private void HandleDiscard()
+    {
+        ResetFields();
+    }
+}
