@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Notifications</h4>

    <div class="mb-4">
        <h6>Notification Channels</h6>

        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif" checked="@EmailNotifications"
                   @onchange="e => EmailNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>

        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif" checked="@PushNotifications"
                   @onchange="e => PushNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>

        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" checked="@WeeklyDigest"
                   @onchange="e => WeeklyDigest = (bool)e.Value!" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h6>Muted Channels</h6>
        <p class="text-muted small">Uncheck a channel to unmute it.</p>

        @foreach (var channel in Channels)
        {
            <div class="form-check mb-1">
                <input class="form-check-input" type="checkbox" id="ch-@channel"
                       checked="@MutedSet.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <label class="form-check-label" for="ch-@channel">#@channel</label>
            </div>
        }
    </div>

    @if (ShowSuccess)
    {
        <div class="alert alert-success py-2">Preferences saved!</div>
    }

    <button class="btn btn-primary" @onclick="HandleSave" disabled="@IsSaving">
        @(IsSaving ? "Saving…" : "Save Preferences")
    </button>
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedSet = new();
    private List<string> Channels = new();
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            Channels = new List<string>(Prefs.MutedChannels);
            MutedSet = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            MutedSet.Add(channel);
        else
            MutedSet.Remove(channel);
    }

    private async Task HandleSave()
    {
        IsSaving = true;
        ShowSuccess = false;
        try
        {
            var updated = new NotificationPrefs(
                EmailNotifications, PushNotifications, WeeklyDigest,
                MutedSet.ToList());
            await OnSave.InvokeAsync(updated);
            ShowSuccess = true;
        }
        finally
        {
            IsSaving = false;
        }
    }
}

