@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    <div class="mb-4">
        <h6>Theme</h6>
        <div class="d-flex gap-3">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                           value="@theme" checked="@(SelectedTheme == theme)"
                           @onchange="() => SelectedTheme = theme" />
                    <label class="form-check-label" for="theme-@theme">@theme</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-4">
        <h6>Font Size</h6>
        <div class="d-flex gap-3">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                           value="@size" checked="@(SelectedFontSize == size)"
                           @onchange="() => SelectedFontSize = size" />
                    <label class="form-check-label" for="fs-@size">@size</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-4">
        <h6>Language</h6>
        <select class="form-select w-auto" @bind="SelectedLanguage">
            @foreach (var lang in Languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <div class="mb-4">
        <h6>Compact Mode</h6>
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode"
                   checked="@CompactMode"
                   @onchange="e => CompactMode = (bool)e.Value!" />
            <label class="form-check-label" for="compactMode">
                Enable compact layout
            </label>
        </div>
    </div>

    <AppearancePreview Theme="@SelectedTheme" FontSize="@SelectedFontSize" CompactMode="@CompactMode" />

    @if (ShowSuccess)
    {
        <div class="alert alert-success py-2 mt-3">Appearance settings saved!</div>
    }

    <div class="mt-3">
        <button class="btn btn-primary" @onclick="HandleSave" disabled="@IsSaving">
            @(IsSaving ? "Saving…" : "Save")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages =
        { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean" };

    protected override void OnParametersSet()
    {
        if (!_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private async Task HandleSave()
    {
        IsSaving = true;
        ShowSuccess = false;
        try
        {
            var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
            await OnSave.InvokeAsync(updated);
            ShowSuccess = true;
        }
        finally
        {
            IsSaving = false;
        }
    }
}

