@page "/settings"
@using sv_9fc3017e169c4be987453dff2adcc320.Services
@namespace sv_9fc3017e169c4be987453dff2adcc320.Components.Pages.Settings
@rendermode InteractiveServer

@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout d-flex">
    <SettingsSidebar ActiveSection="@ActiveSection" OnSectionSelected="SetSection" />

    <div class="settings-content flex-grow-1 p-4">
        @if (IsLoading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading…</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection Profile="@_profile!" OnSave="SaveProfile" />
                    break;

                case "Notifications":
                    <NotificationsSection Prefs="@_notifPrefs!" OnSave="SaveNotifications" />
                    break;

                case "Security":
                    <SecuritySection Settings="@_security!"
                                     OnChangePassword="ChangePassword"
                                     OnRevokeSession="RevokeSession" />
                    break;

                case "Appearance":
                    <AppearanceSection Settings="@_appearance!" OnSave="SaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string ActiveSection = "Profile";
    private bool IsLoading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notifPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
    }

    private async Task LoadAllSettings()
    {
        IsLoading = true;
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _notifPrefs = notifTask.Result;
        _security = securityTask.Result;
        _appearance = appearanceTask.Result;
        IsLoading = false;
    }

    private void SetSection(string section)
    {
        ActiveSection = section;
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notifPrefs = prefs;
    }

    private async Task ChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

.settings-layout {
    min-height: calc(100vh - 7rem);
    margin: -1.5rem;
}

.settings-content {
    max-width: 900px;
}

.settings-section {
    animation: fadeIn 0.15s ease-in;
}

@@keyframes fadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}

